package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class DecimalPercentReverseTest {
 @Test public void thousandthsRatesIncludeZeroWholeAndFractionalPercentages(){Checker checker=new Checker();Set<String> signatures=new HashSet<>();for(int i=0;i<=1000;i++){Question q=DecimalPercentReverse.make(i);assertTrue(signatures.add(q.signature()));assertEquals(Rational.of(i,10),Expression.number(q.answers[0]));assertNotNull(DecimalPercentReverse.read(q));assertTrue(checker.check(q,List.of(),List.of(q.answers[0])).correct());assertFalse(checker.check(q,List.of(),List.of(Rational.of(i+1,10).decimalText())).correct());}assertEquals(1001,signatures.size());assertEquals("0",DecimalPercentReverse.make(0).answers[0]);assertEquals("100",DecimalPercentReverse.make(1000).answers[0]);assertEquals("46.6",DecimalPercentReverse.make(466).answers[0]);}
 @Test public void publicOnlyReverseHelpLeavesTheMainAnswerAlone(){Question original=DecimalPercentReverse.make(466),q=new Question(DecimalPercentReverse.ID,original.prompt,"poison","999");HelpPlan h=HelpPlan.forQuestion(q);assertEquals(4,h.size());assertFalse(h.canTransfer());List<String> fields=List.of("100","0.466","100","46.6");for(int i=0;i<fields.size();i++)assertTrue(h.step(i).accepts(fields.get(i)));assertFalse(h.step(0).accepts("10"));}
 @Test public void exhaustedDomainUsesTheOldestPublicCondition(){Map<String,Integer> recent=new HashMap<>();for(int i=0;i<=1000;i++)recent.put(DecimalPercentReverse.make(i).signature(),i);assertEquals(DecimalPercentReverse.make(0).signature(),DecimalPercentReverse.next(new Random(89),CurriculumLimits.NONE,recent).signature());}
}
